// Sanitizer for rendered document HTML.
//
// The print surface renders markdown with `html: true`, because this dialect
// preserves inline HTML and the fidelity survey records it round-tripping
// byte-identically.
//
// Print is the only surface this guards. It once guarded the split preview too,
// and that preview is gone — Split hosts the real editor now, which has its own
// rendering path and does NOT pass through here. Saying otherwise would let a
// maintainer believe an allowlist runs where it does not. That switch hands every byte of an untrusted
// document straight into the DOM of the webview that holds the native bindings
// — SaveDocument and OpenRecentDocument, with no path restriction. The renderer
// that came before did no such thing only because it could not: it matched
// headings and fences with regular expressions and emitted text nodes, so
// `<img onerror=...>` never became an element in the first place. Adopting a
// real parser removed that accident, and the guarantee has to be stated
// deliberately instead.
//
// Same reasoning as links.js, one level up: allowlist, never denylist. A list
// of dangerous elements is a list you can always add to, and the one you forget
// is the one that ships.
import { safeLinkHref } from './links.js'

// Elements whose CONTENT is code or a fetch instruction rather than prose.
// These are dropped with their subtree; unwrapping them would leave the code
// visible as text, which is honest but noisy, and for <style> would leak rules
// into the app's own stylesheet cascade.
//
// <svg> is here despite being legitimate in a hand-written document: it carries
// its own script elements and its own xlink: URL surface, which is a second
// sanitizer's worth of rules. Mermaid's SVG is injected AFTER this pass and is
// unaffected. The cost is that a document embedding raw SVG shows nothing for
// it in preview and print; that is a real fidelity loss, taken knowingly.
const DROP_WITH_SUBTREE = new Set([
  'script', 'style', 'iframe', 'object', 'embed', 'noscript',
  'template', 'form', 'base', 'meta', 'link', 'svg', 'math',
])

// Elements kept as themselves. Everything generated by markdown-it and its two
// plugins is here, plus the inline HTML a markdown document actually uses.
// Anything else is UNWRAPPED rather than dropped: an unknown tag loses its
// element but keeps its text, so no document content silently disappears.
const KEEP = new Set([
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'br', 'hr',
  'em', 'strong', 'del', 's', 'ins', 'mark', 'small', 'sub', 'sup',
  'code', 'pre', 'kbd', 'samp', 'var', 'abbr', 'cite', 'q', 'blockquote',
  'ul', 'ol', 'li', 'dl', 'dt', 'dd',
  'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td', 'caption',
  'colgroup', 'col',
  'a', 'img', 'figure', 'figcaption',
  'div', 'span', 'section', 'details', 'summary', 'input',
])

// Attributes allowed on any kept element.
//
// `id` is deliberately NOT here. The preview renders inside the app's own
// document, next to elements the app finds by id — #print-root, #wysiwyg —
// and getElementById returns the first match in document order. A document
// that names one of them would be answering queries meant for the application.
// Nothing this renderer generates needs an id; only document-authored anchors
// do, and they lose their targets rather than the app losing its own.
//
// `style` is not here either, for a smaller reason: nothing generated needs it,
// and the renderer this replaced stripped all attributes, so its absence is not
// a regression. `align` covers the common centred-block case.
const GLOBAL_ATTRIBUTES = new Set(['class', 'title', 'dir', 'lang', 'align'])

// Per-element attributes. `checked` and `disabled` are here for the task-list
// plugin's checkboxes, which are the only <input> this renderer emits.
const ELEMENT_ATTRIBUTES = {
  a: ['href'],
  img: ['src', 'alt', 'width', 'height'],
  input: ['type', 'checked', 'disabled'],
  th: ['colspan', 'rowspan', 'scope'],
  td: ['colspan', 'rowspan'],
  ol: ['start', 'reversed'],
  col: ['span'],
  colgroup: ['span'],
  details: ['open'],
}

// safeImageSrc mirrors safeLinkHref for <img>, which cannot share its scheme
// list. An image reference is normally a RELATIVE path that the app resolves
// against the document directory afterwards, and once resolved it is a
// `data:image/...` URI — both of which safeLinkHref refuses, and correctly, for
// a link. Refusing them here would break every embedded image in the product.
//
// data: is admitted only for an image/* mediatype. `data:text/html` in an <img>
// is not a rendering path, but the allowlist should not depend on that being
// true. SVG is admitted because an <img> renders SVG passively: scripts in it
// do not run, which is a browser guarantee rather than a hope, and the asset
// importer accepts .svg files.
export function safeImageSrc(src) {
  const value = String(src).replace(/[\t\n\r]/g, '').replace(/^[\x00-\x20]+|[\x00-\x20]+$/g, '')
  try {
    const resolved = new URL(value, 'https://example.invalid')
    if (resolved.protocol === 'http:' || resolved.protocol === 'https:') return value
    if (resolved.protocol === 'data:' && /^image\/[a-z0-9.+-]+[;,]/i.test(resolved.pathname)) return value
    return null
  } catch {
    return null
  }
}

// sanitizeInto rewrites the subtree of `root` in place to satisfy the rules
// above. It runs on the host element BEFORE mermaid diagrams are drawn into it,
// so mermaid's own output never passes through here.
//
// `keepAttributes` lets the caller keep a marker attribute it wrote itself.
//
// `onRefused({ kind, value })` is how a refusal leaves a trace. Stripping a
// javascript: href is an autonomous security decision taken against untrusted
// content, and a security decision nobody can see afterwards cannot be
// reviewed, tuned, or shown to have fired at all. It is a callback rather than
// an import for the same reason as the code chrome: the recorder lives in the
// application and this module must not depend on it.
export function sanitizeInto(root, { keepAttributes = [], onRefused = null } = {}) {
  const permitted = new Set(keepAttributes)
  const refuse = (kind, value) => onRefused?.({ kind, value })
  // Collected first: the walk mutates the tree, and a live NodeList would skip
  // siblings as elements are unwrapped out from under it.
  const elements = Array.from(root.querySelectorAll('*'))
  for (const el of elements) {
    // An element already removed with an ancestor's subtree has no work left.
    if (!root.contains(el)) continue
    const tag = el.tagName.toLowerCase()

    if (DROP_WITH_SUBTREE.has(tag)) {
      el.remove()
      continue
    }
    if (!KEEP.has(tag)) {
      el.replaceWith(...el.childNodes)
      continue
    }

    const allowed = new Set([
      ...GLOBAL_ATTRIBUTES,
      ...(ELEMENT_ATTRIBUTES[tag] ?? []),
      ...permitted,
    ])
    // Names are collected before removal for the same reason as above:
    // el.attributes is live.
    for (const name of el.getAttributeNames()) {
      if (!allowed.has(name.toLowerCase())) el.removeAttribute(name)
    }

    // URL-bearing attributes are re-checked by value, and the CHECKED string is
    // what gets assigned. Validating one string and writing another is the
    // defect class links.js exists to prevent, not a special case of it.
    if (tag === 'a' && el.hasAttribute('href')) {
      const raw = el.getAttribute('href')
      const safe = safeLinkHref(raw)
      if (safe === null) {
        el.removeAttribute('href')
        // Marked, not merely stripped. An anchor with no href is
        // indistinguishable from one the document never gave a destination,
        // and the difference is exactly what a reader — or a test — needs to
        // see: this link was REFUSED. The attribute is set after the filter
        // pass above, so it is the sanitizer's own mark and not one a document
        // can forge.
        el.dataset.blockedHref = 'true'
        refuse('link', raw)
      } else {
        el.setAttribute('href', safe)
      }
    }
    if (tag === 'img' && el.hasAttribute('src')) {
      const raw = el.getAttribute('src')
      const safe = safeImageSrc(raw)
      if (safe === null) {
        el.removeAttribute('src')
        refuse('image', raw)
      } else {
        el.setAttribute('src', safe)
      }
    }
  }
  return root
}
